#!/usr/bin/env bash
# Usage: install-cargo-about.sh <dest-dir>
#
# Installs a pinned cargo-about release into <dest-dir> after verifying its
# SHA-256, so the third-party license listing shipped with every release is
# generated by the same, publicly visible tool version. Under GitHub Actions
# it also exports CARGO_ABOUT with the installed path.
#
# Kept compatible with the bash 3.2 shipped with macOS.
set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=scripts/lib/fetch-pinned.sh
source "${SCRIPT_DIR}/lib/fetch-pinned.sh"

CARGO_ABOUT_VERSION=0.9.3

dest=${1-}
base_url=${CARGO_ABOUT_BASE_URL:-https://github.com/EmbarkStudios/cargo-about/releases/download/${CARGO_ABOUT_VERSION}}
platform=${CARGO_ABOUT_PLATFORM:-$(uname -s)-$(uname -m)}

die() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 1
}

[[ -n "${dest}" ]] || die "usage: $0 <dest-dir>"

# The listing is generated on Linux runners only; the musl builds run on any
# distribution.
case "${platform}" in
  Linux-x86_64)
    target=x86_64-unknown-linux-musl
    sha256=3ad1e94ea1e63d69d1961f4fb15ccbbe9575d906111f96d2cb4dce6df48f71b4
    ;;
  Linux-aarch64)
    target=aarch64-unknown-linux-musl
    sha256=eb4d9ff6ebd2518152a8308729431a04b3836e71d2bd5ead7aea69f91a71162e
    ;;
  *)
    die "no pinned cargo-about for platform ${platform}"
    ;;
esac
stage=cargo-about-${CARGO_ABOUT_VERSION}-${target}
asset=${stage}.tar.gz

work=$(mktemp -d)
trap 'rm -rf "${work}"' EXIT

fetch_pinned "${base_url}/${asset}" "${sha256}" "${work}/${asset}"
tar -C "${work}" -xzf "${work}/${asset}"
mkdir -p "${dest}"
cp "${work}/${stage}/cargo-about" "${dest}/cargo-about"
"${dest}/cargo-about" --version

export_github_env CARGO_ABOUT "${dest}/cargo-about"
